<section class="page-hero shell compact"><p class="kicker">Delivery details</p><h1><?=!empty($address['guid'])?'Edit address.':'Add an address.'?></h1></section><section class="section section-tight shell narrow-form"><form method="post" class="commerce-form two-col"><?=csrf_field()?><label>Address type<select name="type"><option value="home" <?=($address['type']??'home')==='home'?'selected':''?>>Home</option><option value="work" <?=($address['type']??'')==='work'?'selected':''?>>Work</option><option value="other" <?=($address['type']??'')==='other'?'selected':''?>>Other</option></select></label><label>Recipient name<input name="name" value="<?=e($address['name']??'')?>" required></label><label>Phone<input name="phone" value="<?=e($address['phone']??'')?>" inputmode="tel"></label><label>Address line 1<input name="line1" value="<?=e($address['line1']??'')?>" required></label><label class="span-2">Address line 2<input name="line2" value="<?=e($address['line2']??'')?>"></label><label>Landmark<input name="landmark" value="<?=e($address['landmark']??'')?>"></label><label>City<input name="city" value="<?=e($address['city']??'')?>" required></label><label>State<input name="state" value="<?=e($address['state']??'Maharashtra')?>" required></label><label>Pincode<input name="pincode" value="<?=e($address['pincode']??'')?>" inputmode="numeric" pattern="[0-9]{6}" required></label><label class="checkline span-2"><input type="checkbox" name="is_default" value="1" <?=!empty($address['is_default'])?'checked':''?>> Use as my default delivery address</label><div class="form-actions span-2"><a class="btn outline" href="<?=e(url('/account/addresses'))?>">Cancel</a><button class="btn dark" type="submit">Save address</button></div></form></section>
